// normalise a link that arrived via a button tap into the same shape
// the YouTube chain expects (message.text), so those nodes stay unchanged
const text = $('Telegram Trigger').first().json.callback_query.message.reply_to_message.text;
return [{ json: { message: { text } } }];

const html = $input.first().json.data;

// Try pattern 1: the JSON blob embedded in most channel/video pages
let match = html.match(/"channelId":"(UC[a-zA-Z0-9_-]{22})"/);

// Try pattern 2: the canonical link tag (more reliable across page types)
if (!match) {
  match = html.match(/youtube\.com\/channel\/(UC[a-zA-Z0-9_-]{22})/);
}

if (!match) {
  throw new Error("Could not find a channel ID in the page HTML");
}

const channelId = match[1];

const titleMatch = html.match(/<title>(.*?)<\/title>/);
const channelName = titleMatch
  ? titleMatch[1].replace(/ - YouTube$/, '')
  : 'Unknown channel';

return [{
  json: {
    channelId,
    channelName,
    rssUrl: `https://www.youtube.com/feeds/videos.xml?channel_id=${channelId}`
  }
}];

