function stripHtml(s) {
  return s
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function unescapeJson(s) {
  try { return JSON.parse('"' + s + '"'); } catch (e) { return ''; }
}

let title = '';
let author = '';
let content = '';
let source = '';

const t = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
if (t) title = stripHtml(t[1]);

if (meta.isYouTube) {
  title = title.replace(/\s*-\s*YouTube$/, '');

  const a = html.match(/"ownerChannelName":"((?:\\.|[^"\\])*)"/);
  if (a) author = unescapeJson(a[1]);

  let description = '';
  const d = html.match(/"shortDescription":"((?:\\.|[^"\\])*)"/);
  if (d) description = unescapeJson(d[1]);

  if (!description) {
    const om = html.match(/<meta property="og:description" content="([^"]*)"/i);
    if (om) description = stripHtml(om[1]);
  }
  if (!description) {
    const nm = html.match(/<meta name="description" content="([^"]*)"/i);
    if (nm) description = stripHtml(nm[1]);
  }

  const header = 'Video title: ' + title + (author ? '\nChannel: ' + author : '');
  if (description && description.length > 40) {
    content = header + '\n\nVideo description:\n' + description;
    source = 'description';
  } else {
    content = header;
    source = 'title only';
  }
} else {
  const body = stripHtml(html);
  if (body.length > 200) {
    content = 'Page title: ' + title + '\n\nPage text:\n' + body;
    source = 'page text';
  } else {
    content = 'Page title: ' + title;
    source = 'title only';
  }
}

const MAX = 6000;
if (content.length > MAX) content = content.slice(0, MAX) + ' ...[truncated]';

return [{ json: { url: meta.link, title, author, content, source } }];

